/* Animal Crossing set additions — cards appended after acrs.js.
   (acrs.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'acrs.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('acrs');
  if (!S) return;
  var extra = [{"name":"Tom Nook","rarity":"chase","id":"tom-nook","subtitle":"Special Character","details":"The tanuki who founded Nook Inc., sells you your first house and happily extends the loan every time you expand it, interest-free, forever.","image":"https://dodo.ac/np/images/e/e3/Tom_Nook_NH.png"},{"name":"Isabelle","rarity":"chase","id":"isabelle","subtitle":"Special Character","details":"The shih tzu assistant introduced in New Leaf who runs the front desk, delivers the morning announcements and keeps town life cheerful.","image":"https://dodo.ac/np/images/9/95/Isabelle_NH.png"},{"name":"K.K. Slider","rarity":"chase","id":"k-k-slider","subtitle":"Special Character","details":"The travelling guitar dog who plays a free concert every Saturday night and hands over a copy of the song to anyone who sits and listens.","image":"https://dodo.ac/np/images/8/81/K.K._Slider_NH.png"},{"name":"Blathers","rarity":"legendary","id":"blathers","subtitle":"Special Character","details":"The museum's owl director who assesses fossils and fills every exhibit hall, though a donated bug still makes him shudder in horror.","image":"https://dodo.ac/np/images/1/1b/Blathers_NH.png"},{"name":"Celeste","rarity":"legendary","id":"celeste","subtitle":"Special Character","details":"Blathers' younger sister, the stargazing owl who appears on clear nights to share zodiac DIY recipes and stories about the constellations.","image":"https://dodo.ac/np/images/e/e0/Celeste_NL.png"},{"name":"Redd","rarity":"legendary","id":"redd","subtitle":"Special Character","details":"The fox dealer who sells famous paintings and sculptures from his shadowy gallery, mixing genuine masterpieces in among convincing forgeries.","image":"https://dodo.ac/np/images/4/42/Redd_NH.png"},{"name":"Rover","rarity":"legendary","id":"rover","subtitle":"Special Character","details":"The blue cat who has greeted new arrivals since the first game, asking the friendly questions that decide your name, town and face.","image":"https://dodo.ac/np/images/5/54/Rover_NL.png"},{"name":"Kapp'n","rarity":"legendary","id":"kappn","subtitle":"Special Character","details":"The kappa boatman who ferries you to offshore islands while singing rambling sea shanties about his family, his dreams and his dinner.","image":"https://dodo.ac/np/images/9/9b/Kapp%27n_NL.png"},{"name":"Tortimer","rarity":"legendary","id":"tortimer","subtitle":"Special Character","details":"The elderly tortoise who served as mayor through the earliest games, then retired to his own island to host tours and hand out prizes.","image":"https://dodo.ac/np/images/4/4c/Tortimer_NL.png"},{"name":"Mr. Resetti","rarity":"legendary","id":"mr-resetti","subtitle":"Special Character","details":"The mole who once erupted from the ground to scold players who reset without saving, later mellowing into work with the Rescue Service.","image":"https://dodo.ac/np/images/a/a1/Mr._Resetti_NH.png"},{"name":"Sable","rarity":"epic","id":"sable","subtitle":"Special Character","details":"The shy hedgehog who sews in silence at the back of the Able Sisters shop, only sharing her family's story with customers who visit daily.","image":"https://dodo.ac/np/images/1/19/Sable_NH.png"},{"name":"Mabel","rarity":"epic","id":"mabel","subtitle":"Special Character","details":"The bright, welcoming hedgehog who runs the front counter of the Able Sisters, while her sister Sable works the sewing machine behind her.","image":"https://dodo.ac/np/images/8/80/Mabel_NH.png"},{"name":"Timmy & Tommy","rarity":"epic","id":"timmy-tommy","subtitle":"Special Character","details":"Tom Nook's twin nephews and apprentices, who run Nook's Cranny together, echo each other's sentences and dream of a store of their own.","image":"https://dodo.ac/np/images/a/a1/Timmy_%26_Tommy_NH_Transparent.png"},{"name":"Gulliver","rarity":"epic","id":"gulliver","subtitle":"Special Character","details":"The seagull sailor who forever washes up unconscious on the beach; help him recover his communicator parts and a souvenir arrives by post.","image":"https://dodo.ac/np/images/4/40/Gulliver_NH_2.png"},{"name":"Wisp","rarity":"epic","id":"wisp","subtitle":"Special Character","details":"The gentle ghost who takes fright after dark and scatters five pieces of his spirit around town, rewarding whoever gathers them all up.","image":"https://dodo.ac/np/images/c/c3/Wisp_NH.png"},{"name":"Saharah","rarity":"epic","id":"saharah","subtitle":"Special Character","details":"The wandering camel who sells mystery wallpapers, floors and rugs sight unseen, speaking in riddles and travelling wherever the road leads.","image":"https://dodo.ac/np/images/c/c9/Saharah_NH.png"},{"name":"Katrina","rarity":"epic","id":"katrina","subtitle":"Special Character","details":"The panther fortune-teller whose tent readings reveal the day's luck, measure friendships and, for a fee, wash away a stretch of bad fortune.","image":"https://dodo.ac/np/images/6/67/Katrina_NH.png"},{"name":"Daisy Mae","rarity":"epic","id":"daisy-mae","subtitle":"Special Character","details":"Joan's granddaughter, who takes over the Sunday turnip route in New Horizons, selling stalks every morning under the name Sow Joan's.","image":"https://dodo.ac/np/images/6/69/Daisy_Mae_NH.png"},{"name":"Harriet","rarity":"rare","id":"harriet","subtitle":"Special Character","details":"The pink poodle who runs Shampoodle, quizzing customers on their mood and style before giving them a bold new haircut at her salon chair.","image":"https://dodo.ac/np/images/3/3f/Harriet_NH.png"},{"name":"Brewster","rarity":"rare","id":"brewster","subtitle":"Special Character","details":"The soft-spoken pigeon barista of The Roost, the museum café where he brews each cup to order and advises you to drink it while it is hot.","image":"https://dodo.ac/np/images/3/38/Brewster_NH.png"},{"name":"Flick","rarity":"rare","id":"flick","subtitle":"Special Character","details":"The red chameleon artist who hosts the Bug-Off, pays above shop prices for insects and carves any bug you bring him into a collectable model.","image":"https://dodo.ac/np/images/f/f4/Flick_NH.png"},{"name":"C.J.","rarity":"rare","id":"c-j","subtitle":"Special Character","details":"The beaver streamer who hosts the Fishing Tourney, buys fish at a premium and commissions detailed models of your finest catches to order.","image":"https://dodo.ac/np/images/4/49/C.J._NH.png"},{"name":"Orville","rarity":"rare","id":"orville","subtitle":"Special Character","details":"The grounded dodo behind the Dodo Airlines desk, who handles check-ins, opens the airport gates and radios flight updates to his brother.","image":"https://dodo.ac/np/images/0/09/Orville_NH.png"},{"name":"Wilbur","rarity":"rare","id":"wilbur","subtitle":"Special Character","details":"The sunglasses-wearing dodo pilot of Dodo Airlines, who flies you to mystery islands and narrates every trip in cheerful aviation slang.","image":"https://dodo.ac/np/images/3/3b/Wilbur_NH.png"},{"name":"Leif","rarity":"rare","id":"leif","subtitle":"Special Character","details":"The gentle sloth gardener who sells flower seeds, shrubs and pumpkins, and once ran the gardening shop beside Nook's store in New Leaf.","image":"https://dodo.ac/np/images/1/1c/Leif_NH.png"},{"name":"Kicks","rarity":"rare","id":"kicks","subtitle":"Special Character","details":"The skunk who began shining shoes on the city streets and worked his way up to selling shoes, socks and bags from a shop of his very own.","image":"https://dodo.ac/np/images/c/c7/Kicks_NH.png"},{"name":"Label","rarity":"rare","id":"label","subtitle":"Special Character","details":"The middle Able sister, who left home to design under the name Labelle and later returns to test players with themed fashion challenges.","image":"https://dodo.ac/np/images/0/04/Label_NH_Model.png"},{"name":"Joan","rarity":"rare","id":"joan","subtitle":"Special Character","details":"The boar who sold turnips on Sunday mornings for generations, pricing her white and red stalks by the week and founding the Stalk Market.","image":"https://dodo.ac/np/images/d/d1/Joan_NH.png"},{"name":"Pascal","rarity":"rare","id":"pascal","subtitle":"Special Character","details":"The red sea otter who pops up when you find a scallop while diving, trading a pearl or mermaid recipe for it along with a far-out thought.","image":"https://dodo.ac/np/images/0/03/Pascal_NH.png"},{"name":"Luna","rarity":"rare","id":"luna","subtitle":"Special Character","details":"The tapir who runs the Dream Suite, lulling visitors to sleep so they can wander through dream versions of other towns and islands.","image":"https://dodo.ac/np/images/d/d9/Luna_NH.png"},{"name":"Booker","rarity":"uncommon","id":"booker","subtitle":"Special Character","details":"The apologetic bulldog guard who minds the lost and found, hedging every answer because he is never quite certain about anything at all.","image":"https://dodo.ac/np/images/8/80/Booker_NLWa.png"},{"name":"Copper","rarity":"uncommon","id":"copper","subtitle":"Special Character","details":"The keen, upright guard dog who stands at attention beside Booker, delivering the day's news and visitor announcements with total certainty.","image":"https://dodo.ac/np/images/9/92/Copper_NLWa.png"},{"name":"Pelly","rarity":"uncommon","id":"pelly","subtitle":"Special Character","details":"The cheerful white pelican who staffs the post office counter by day, taking letters, parcels and savings deposits with unfailing politeness.","image":"https://dodo.ac/np/images/6/62/Pelly_NLWa.png"},{"name":"Phyllis","rarity":"uncommon","id":"phyllis","subtitle":"Special Character","details":"The purple pelican who works the post office night shift, handling the same letters as her sister Pelly with far less patience for small talk.","image":"https://dodo.ac/np/images/b/b9/Phyllis_NLWa.png"},{"name":"Pete","rarity":"uncommon","id":"pete","subtitle":"Special Character","details":"The pelican postman who delivers mail twice a day and can be seen streaking across the sky at nine and five, satchel slung over his wing.","image":"https://dodo.ac/np/images/4/46/Pete_NLWa.png"},{"name":"Wendell","rarity":"uncommon","id":"wendell","subtitle":"Special Character","details":"The wandering walrus artist who once traded his wallpaper designs for fish, then moved online to share patterns with towns everywhere.","image":"https://dodo.ac/np/images/a/a2/Wendell_NLWa.png"},{"name":"Harvey","rarity":"uncommon","id":"harvey","subtitle":"Special Character","details":"The laid-back dog known as Harv, whose island is home to a photo studio and a plaza of merchant stalls for visiting players to browse.","image":"https://dodo.ac/np/images/a/ac/Harvey_NH.png"},{"name":"Digby","rarity":"uncommon","id":"digby","subtitle":"Special Character","details":"Isabelle's twin brother, the dog in the red coat who greeted visitors at the Happy Home Showcase and later helps out at Paradise Planning.","image":"https://dodo.ac/np/images/f/f2/Digby_NL.png"},{"name":"Lottie","rarity":"uncommon","id":"lottie","subtitle":"Special Character","details":"The cheerful pink otter who trains new designers at Nook's Homes and goes on to found Paradise Planning, matching clients with vacation homes.","image":"https://dodo.ac/np/images/c/c4/Lottie_HHP.png"},{"name":"Dr. Shrunk","rarity":"uncommon","id":"dr-shrunk","subtitle":"Special Character","details":"The axolotl comedian whose stage act teaches a new reaction with every visit, delivering each joke with a flourish and a shower of flowers.","image":"https://dodo.ac/np/images/2/2a/Shrunk_NLWa.png"},{"name":"Gullivarrr","rarity":"uncommon","id":"gullivarrr","subtitle":"Special Character","details":"Gulliver's pirate persona, hauled dripping from the sea in full captain's gear, who rewards rescuers with furniture fit for a pirate ship.","image":"https://dodo.ac/np/images/9/9d/Gullivarrr_NH.png"},{"name":"Porter","rarity":"common","id":"porter","subtitle":"Special Character","details":"The monkey stationmaster who operates the train station gates, checking tickets and waving travellers off to visit friends in other towns.","image":"https://dodo.ac/np/images/8/87/Porter_NLWa.png"},{"name":"Reese","rarity":"common","id":"reese","subtitle":"Special Character","details":"The pink alpaca who runs the buying counter at Re-Tail, offering fair prices for unwanted furniture while her husband Cyrus customises it.","image":"https://dodo.ac/np/images/f/fe/Reese_NH.png"},{"name":"Cyrus","rarity":"common","id":"cyrus","subtitle":"Special Character","details":"The blue alpaca craftsman of Re-Tail, who refurbishes furniture into new colours and styles, provided you wake him from his counter nap first.","image":"https://dodo.ac/np/images/8/8a/Cyrus_NH.png"},{"name":"Gracie","rarity":"common","id":"gracie","subtitle":"Special Character","details":"The giraffe fashion designer behind GracieGrace, whose demanding fashion checks and seasonal sales set the standard for luxury in town.","image":"https://dodo.ac/np/images/0/00/Gracie_NLWa.png"},{"name":"Lyle","rarity":"common","id":"lyle","subtitle":"Special Character","details":"The fast-talking weasel who moved from selling insurance and grading homes for the Happy Room Academy into selling houses with Nook's Homes.","image":"https://dodo.ac/np/images/d/d0/Lyle_NLWa.png"},{"name":"Zipper T. Bunny","rarity":"common","id":"zipper-t-bunny","subtitle":"Special Character","details":"The Bunny Day host who hops around hiding eggs of every kind and firmly denies, through the visible zipper, that he is wearing a costume.","image":"https://dodo.ac/np/images/e/e3/Zipper_NH.png"},{"name":"Jack","rarity":"common","id":"jack","subtitle":"Special Character","details":"The self-styled Czar of Halloween, a pumpkin-headed figure who appears every October 31st to trade candy for spooky seasonal furniture.","image":"https://dodo.ac/np/images/e/e6/Jack_NH.png"},{"name":"Jingle","rarity":"common","id":"jingle","subtitle":"Special Character","details":"The black-nosed reindeer who delivers presents on Toy Day, quietly enlisting players to help match the right gift to every villager in town.","image":"https://dodo.ac/np/images/5/54/Jingle_NH_Transparent.png"},{"name":"Pavé","rarity":"common","id":"pave","subtitle":"Special Character","details":"The flamboyant peacock who dances through Festivale demanding feathers, trading them piece by piece for his own dazzling furniture series.","image":"https://dodo.ac/np/images/c/c5/Pav%C3%A9_NH.png"},{"name":"Nat","rarity":"common","id":"nat","subtitle":"Special Character","details":"The elderly chameleon who hosted the original Bug-Off contests, judging each insect entry carefully by its size, colour and rarity in person.","image":"https://dodo.ac/np/images/9/96/Nat_NH.png"},{"name":"Chip","rarity":"common","id":"chip","subtitle":"Special Character","details":"The beaver who hosted the original fishing tournaments, measuring every entry the honest way: by eating the catch himself, bones and all.","image":"https://dodo.ac/np/images/c/c9/Chip_NLWa.png"},{"name":"The Museum","rarity":"legendary","id":"the-museum","subtitle":"Location","details":"Blathers' grand collection hall for fossils, fish, bugs and art, which grows donation by donation from an empty tent into a town landmark.","image":"https://dodo.ac/np/images/9/96/NH_Museum_Exterior.png"},{"name":"Nook's Cranny","rarity":"legendary","id":"nooks-cranny","subtitle":"Location","details":"Timmy and Tommy's general store, stocked daily with furniture, tools and seeds, and expanding into a department store as the town prospers.","image":"https://dodo.ac/np/images/4/48/NH_Nook%27s_Cranny_Upgraded_Exterior.jpg"},{"name":"Able Sisters","rarity":"epic","id":"able-sisters","subtitle":"Location","details":"The clothing shop run by Mabel and Sable, where players buy outfits, display their own designs and use the kiosk to share patterns worldwide.","image":"https://dodo.ac/np/images/d/df/Able_Sisters_NH.png"},{"name":"Town Hall / Resident Services","rarity":"epic","id":"town-hall-resident-services","subtitle":"Location","details":"The town's civic heart, first a hall where Tortimer and Isabelle worked, later Resident Services, where island business is handled daily.","image":"https://dodo.ac/np/images/9/9f/NH_Resident_Services_Building.jpg"},{"name":"The Roost","rarity":"epic","id":"the-roost","subtitle":"Location","details":"Brewster's quiet café, first tucked into the museum basement, where a single cup of coffee, served exactly right, became a daily ritual.","image":"https://dodo.ac/np/images/b/b8/NH_The_Roost_Interior.jpg"},{"name":"Dodo Airlines Airport","rarity":"epic","id":"dodo-airlines-airport","subtitle":"Location","details":"The island's small airport, run by Orville and Wilbur, and the only departure point for flights to friends, mystery islands and work trips.","image":"https://dodo.ac/np/images/0/02/Airport_NH.png"},{"name":"Harv's Island","rarity":"rare","id":"harvs-island","subtitle":"Location","details":"Harvey's island retreat, home to the Photopia photo studio and a co-op plaza where travelling merchants set up permanent stalls to visit.","image":"https://dodo.ac/np/images/a/af/NH_Harv%27s_Island.jpg"},{"name":"The Campsite","rarity":"rare","id":"the-campsite","subtitle":"Location","details":"The clearing set aside for visiting campers, who play games, tell stories and can be persuaded to move into town for good if they settle in.","image":"https://dodo.ac/np/images/1/18/NH_Campsite_Exterior.png"},{"name":"Main Street","rarity":"rare","id":"main-street","subtitle":"Location","details":"New Leaf's shopping row across the train tracks, lined in time with the museum shop, Kicks, Shampoodle, Club LOL and the Dream Suite.","image":"https://dodo.ac/np/images/2/2e/NL_Main_Street_Entrance.png"},{"name":"Re-Tail","rarity":"rare","id":"re-tail","subtitle":"Location","details":"Reese and Cyrus' flea-market shop in New Leaf, where villagers put items up for sale and furniture can be refurbished into new colourways.","image":"https://dodo.ac/np/images/b/bf/NL_Re-Tail_Exterior.png"},{"name":"Post Office","rarity":"rare","id":"post-office","subtitle":"Location","details":"The counter where Pelly by day and Phyllis by night handle letters, parcels and the town savings account across the earliest generations.","image":"https://dodo.ac/np/images/d/d3/NL_Post_Office_Interior.png"},{"name":"Police Station","rarity":"rare","id":"police-station","subtitle":"Location","details":"Booker and Copper's small station, home to the lost and found, where anything left lying around town eventually turns up waiting for its owner.","image":"https://dodo.ac/np/images/e/ea/PG_Police_Station_Exterior.png"},{"name":"Dream Suite","rarity":"uncommon","id":"dream-suite","subtitle":"Location","details":"Luna's Main Street establishment, where a short nap in a special bed sends you wandering through dream copies of towns from around the world.","image":"https://dodo.ac/np/images/d/d7/NL_Dream_Suite_Interior.jpg"},{"name":"Shampoodle","rarity":"uncommon","id":"shampoodle","subtitle":"Location","details":"Harriet's hair salon, found inside Nookington's, in the city, on Main Street and at Harv's Island, where a quiz decides your new hairstyle.","image":"https://dodo.ac/np/images/8/89/CF_Shampoodle_Exterior.png"},{"name":"GracieGrace","rarity":"uncommon","id":"graciegrace","subtitle":"Location","details":"Gracie's luxury boutique, selling designer furniture in four seasonal themes at prices that made it the ultimate test of a player's savings.","image":"https://dodo.ac/np/images/d/d2/NL_GracieGrace_Interior.jpg"},{"name":"Jolly Redd's Treasure Trawler","rarity":"uncommon","id":"jolly-redds-treasure-trawler","subtitle":"Location","details":"Redd's shadowy gallery boat, moored at the island's secret beach, where masterpieces and forgeries alike are sold under a strict no-refunds sign.","image":"https://dodo.ac/np/images/4/4f/NH_Update_2_Redd_Ship.jpg"},{"name":"Katrina's Fortune Shop","rarity":"uncommon","id":"katrinas-fortune-shop","subtitle":"Location","details":"Katrina's fortune-telling tent and later her Harv's Island stall, where luck is read, friendship is measured and bad fortune can be cleansed.","image":"https://dodo.ac/np/images/f/f8/NL_Fortune_Shop_Interior.jpg"},{"name":"Reset Surveillance Center","rarity":"uncommon","id":"reset-surveillance-center","subtitle":"Location","details":"Resetti and Don's underground monitoring base, hidden beneath the town and open to lucky visitors on occasional evenings in the city era.","image":"https://dodo.ac/np/images/6/60/NL_Reset_Surveillance_Center_Entrance.jpg"},{"name":"Tortimer Island","rarity":"uncommon","id":"tortimer-island","subtitle":"Location","details":"The former mayor's tropical resort in New Leaf, reached by Kapp'n's boat, offering tours, minigames and rare beetles under endless summer sun.","image":"https://dodo.ac/np/images/9/91/NL_Tortimer_Island_Beach.png"},{"name":"Club LOL","rarity":"uncommon","id":"club-lol","subtitle":"Location","details":"Dr. Shrunk's Main Street comedy club, where afternoon shows teach new reactions and DJ K.K. turns the room into a dance floor at night.","image":"https://dodo.ac/np/images/1/14/NL_Club_LOL_Interior.png"},{"name":"Train Station","rarity":"common","id":"train-station","subtitle":"Location","details":"Porter's station and the original gateway between towns, where the arrival of a friend's train was the highlight of a multiplayer session.","image":"https://dodo.ac/np/images/8/8e/NL_Train_Station_Exterior.jpg"},{"name":"The Dump","rarity":"common","id":"the-dump","subtitle":"Location","details":"The fenced plot in the original town where unwanted furniture was left behind, and where early risers sometimes found a free treasure waiting.","image":"https://dodo.ac/np/images/f/f4/PG_Dump.png"},{"name":"The City","rarity":"common","id":"the-city","subtitle":"Location","details":"City Folk's bus-ride downtown plaza, gathering GracieGrace, Shampoodle, the Happy Room Academy, the theatre and Katrina into one trip.","image":"https://dodo.ac/np/images/3/38/CF_City.jpg"},{"name":"Wishing Well","rarity":"common","id":"wishing-well","subtitle":"Location","details":"The shrine-like well at the heart of the original town, where event speeches were given and players apologised for weeds and neglected chores.","image":"https://dodo.ac/np/images/5/5e/PG_Wishing_Well.png"},{"name":"Lighthouse","rarity":"common","id":"lighthouse","subtitle":"Location","details":"The coastal tower overlooking the shore, a town landmark players could climb during events and later build as a public work of their own design.","image":"https://dodo.ac/np/images/4/41/CF_Lighthouse.jpg"},{"name":"The Campground","rarity":"common","id":"the-campground","subtitle":"Location","details":"The Welcome amiibo campsite beside New Leaf towns, where Harvey keeps the fire lit and summoned visitors park their campers for the day.","image":"https://dodo.ac/np/images/d/d0/Campground_NLWa_Artwork.png"},{"name":"Nook's Homes","rarity":"common","id":"nooks-homes","subtitle":"Location","details":"The Main Street home-sales office of Tom Nook, Lyle and Lottie, arranging house expansions, exteriors and full remodels for a growing mortgage.","image":"https://dodo.ac/np/images/6/64/Nook%27s_Homes_HHD_Artwork.png"},{"name":"Town Gate","rarity":"common","id":"town-gate","subtitle":"Location","details":"Booker and Copper's checkpoint in Wild World and City Folk, where the town flag flew and visitors from other towns arrived and departed.","image":"https://dodo.ac/np/images/9/90/CF_Checkpoint_Exterior_%28Castle%29.jpg"},{"name":"Bulletin Board","rarity":"common","id":"bulletin-board","subtitle":"Location","details":"The notice board beside the station and plaza, carrying event announcements, tournament results, villager news and the occasional lost item note.","image":"https://dodo.ac/np/images/b/be/NH_Bulletin_Board.jpg"},{"name":"The Pier","rarity":"common","id":"the-pier","subtitle":"Location","details":"The wooden dock stretching into the sea on every island shore, a prime fishing spot, Kapp'n's mooring and the best seat for fireworks night.","image":"https://dodo.ac/np/images/2/25/NL_Dock.png"},{"name":"Bubblegum K.K.","rarity":"chase","id":"bubblegum-k-k","subtitle":"Song","details":"K.K. Slider's sugary pop hit wraps bright synths and a candy-pink album cover around the catchiest hook in his catalogue, a Saturday-night favourite.","image":"https://dodo.ac/np/images/6/69/Bubblegum_K.K._NH_Texture.png"},{"name":"Animal City","rarity":"legendary","id":"animal-city","subtitle":"Song","details":"This secret request-only track reworks the bustling City theme from City Folk into a K.K. performance you can never buy from the Nook Shopping catalogue.","image":"https://dodo.ac/np/images/1/1f/Animal_City_NH_Texture.png"},{"name":"Drivin'","rarity":"legendary","id":"drivin","subtitle":"Song","details":"A hidden request-only song with a breezy, windows-down groove, Drivin' rewards players who type its exact title to K.K. at a Saturday show.","image":"https://dodo.ac/np/images/1/1f/Drivin%27_NH_Texture.png"},{"name":"Farewell","rarity":"legendary","id":"farewell","subtitle":"Song","details":"Farewell is the wistful secret song hidden behind K.K.'s request list, a quiet goodbye track about leaving town and the friends made along the way.","image":"https://dodo.ac/np/images/c/c3/Farewell_NH_Texture.png"},{"name":"K.K. Cruisin'","rarity":"epic","id":"k-k-cruisin","subtitle":"Song","details":"Silky guitar and a laid-back beat have made K.K. Cruisin' a Saturday-night staple since the GameCube days, perfect for a slow drive around town.","image":"https://dodo.ac/np/images/f/f4/K.K._Cruisin%27_NH_Texture.png"},{"name":"Go K.K. Rider","rarity":"epic","id":"go-k-k-rider","subtitle":"Song","details":"A triumphant tokusatsu hero theme with shouted energy and marching drums, Go K.K. Rider turns any plaza into the opening credits of a sentai show.","image":"https://dodo.ac/np/images/e/e4/Go_K.K._Rider_NH_Texture.png"},{"name":"K.K. Metal","rarity":"epic","id":"k-k-metal","subtitle":"Song","details":"K.K. Metal tears through double-kick drums and shredding guitar, proof the mellow coffeehouse dog can headline a full-throttle metal set.","image":"https://dodo.ac/np/images/2/28/K.K._Metal_NH_Texture.png"},{"name":"Stale Cupcakes","rarity":"epic","id":"stale-cupcakes","subtitle":"Song","details":"A gentle piano lullaby with a bittersweet ache, Stale Cupcakes became a favourite backing track for quiet rooms, cafés and rainy-day island tours.","image":"https://dodo.ac/np/images/e/ef/Stale_Cupcakes_NH_Texture.png"},{"name":"K.K. Disco","rarity":"epic","id":"k-k-disco","subtitle":"Song","details":"Mirror-ball funk, wah guitar and a vocoder hook make K.K. Disco the catalogue's pure dance-floor number, built for plaza parties and club rooms.","image":"https://dodo.ac/np/images/c/ce/K.K._Disco_NH_Texture.png"},{"name":"Welcome Horizons","rarity":"rare","id":"welcome-horizons","subtitle":"Song","details":"K.K. hands you this K.K.-style take on the New Horizons theme at his first island concert, a souvenir of the day the music officially arrives.","image":"https://dodo.ac/np/images/f/f4/Welcome_Horizons_NH_Texture.png"},{"name":"K.K. Birthday","rarity":"rare","id":"k-k-birthday","subtitle":"Song","details":"K.K. only performs this cheerful song live on your birthday, complete with a personalised message, making its album a once-a-year keepsake.","image":"https://dodo.ac/np/images/f/fa/K.K._Birthday_NH_Texture.png"},{"name":"DJ K.K.","rarity":"rare","id":"dj-k-k","subtitle":"Song","details":"Credited to K.K.'s DJ alter ego, this pulsing club track first spun at Club LOL and still turns any basement dance floor into a Saturday night.","image":"https://dodo.ac/np/images/5/5e/DJ_K.K._NH_Texture.png"},{"name":"K.K. House","rarity":"rare","id":"k-k-house","subtitle":"Song","details":"Deep basslines and chopped vocal samples drive K.K. House, the deep-house cut that transforms a plain basement into an island club after dark.","image":"https://dodo.ac/np/images/f/fa/K.K._House_NH_Texture.png"},{"name":"Café K.K.","rarity":"rare","id":"cafe-k-k","subtitle":"Song","details":"Accordion-led Parisian jazz drifts through Café K.K., a smoky little number made for Brewster's counter, small tables and very slow afternoons.","image":"https://dodo.ac/np/images/3/31/Caf%C3%A9_K.K._NH_Texture.png"},{"name":"K.K. Island","rarity":"rare","id":"k-k-island","subtitle":"Song","details":"Steel drums and a swaying rhythm carry K.K. Island, the sound of a slow afternoon by the sea with a coconut drink and nowhere else to be.","image":"https://dodo.ac/np/images/6/64/K.K._Island_NH_Texture.png"},{"name":"Spring Blossoms","rarity":"rare","id":"spring-blossoms","subtitle":"Song","details":"Written for cherry-blossom season, Spring Blossoms pairs a light festival melody with the brief weeks when petals drift over town each spring.","image":"https://dodo.ac/np/images/3/32/Spring_Blossoms_NH_Texture.png"},{"name":"Agent K.K.","rarity":"uncommon","id":"agent-k-k","subtitle":"Song","details":"Sneaky brass and tiptoeing bass make Agent K.K. a spy-film theme in miniature, ideal for secret bases, stakeouts and villagers up to something.","image":"https://dodo.ac/np/images/8/83/Agent_K.K._NH_Texture.png"},{"name":"K.K. Adventure","rarity":"uncommon","id":"k-k-adventure","subtitle":"Song","details":"A swashbuckling orchestral romp with bold horns and rolling drums, K.K. Adventure scores treasure hunts, pirate coves and heroic departures.","image":"https://dodo.ac/np/images/e/eb/K.K._Adventure_NH_Texture.png"},{"name":"K.K. Jazz","rarity":"uncommon","id":"k-k-jazz","subtitle":"Song","details":"Brushed drums, walking bass and a cool piano lead make K.K. Jazz the catalogue's straight-ahead combo session, relaxed but quietly virtuosic.","image":"https://dodo.ac/np/images/0/00/K.K._Jazz_NH_Texture.png"},{"name":"K.K. Rock","rarity":"uncommon","id":"k-k-rock","subtitle":"Song","details":"Garage-rock guitars and a stomping beat push K.K. Rock to the raucous end of the catalogue, best played loud in a room full of instruments.","image":"https://dodo.ac/np/images/0/0e/K.K._Rock_NH_Texture.png"},{"name":"K.K. Synth","rarity":"uncommon","id":"k-k-synth","subtitle":"Song","details":"A dreamy analog-synth wash added late to the catalogue, K.K. Synth drifts like a lullaby beamed in from a very calm, very distant space station.","image":"https://dodo.ac/np/images/4/46/K.K._Synth_NH_Texture.png"},{"name":"K.K. Technopop","rarity":"uncommon","id":"k-k-technopop","subtitle":"Song","details":"Bleepy, hyper-catchy and relentlessly cheerful, K.K. Technopop is an earworm of bleeps and beats that could power an arcade for a whole evening.","image":"https://dodo.ac/np/images/f/f5/K.K._Technopop_NH_Texture.png"},{"name":"K.K. Bossa","rarity":"uncommon","id":"k-k-bossa","subtitle":"Song","details":"Feather-light guitar and soft percussion make K.K. Bossa a bossa nova for beach chairs and coffee, best heard within sight of the ocean.","image":"https://dodo.ac/np/images/c/cc/K.K._Bossa_NH_Texture.png"},{"name":"Forest Life","rarity":"uncommon","id":"forest-life","subtitle":"Song","details":"A quiet woodland theme nodding to the hourly forest music of the original game, Forest Life suits nature trails, campsites and mossy corners.","image":"https://dodo.ac/np/images/b/b1/Forest_Life_NH_Texture.png"},{"name":"Marine Song 2001","rarity":"uncommon","id":"marine-song-2001","subtitle":"Song","details":"This track reworks the sea shanty Kapp'n sang on boat rides in the 2001 original, turning a ferry jingle into a full K.K. album performance.","image":"https://dodo.ac/np/images/a/af/Marine_Song_2001_NH_Texture.png"},{"name":"Space K.K.","rarity":"uncommon","id":"space-k-k","subtitle":"Song","details":"Minimal, drifting and a little uncanny, Space K.K. is space-age lounge music for sci-fi rooms, observatories and late-night stargazing sessions.","image":"https://dodo.ac/np/images/c/c6/Space_K.K._NH_Texture.png"},{"name":"The K. Funk","rarity":"uncommon","id":"the-k-funk","subtitle":"Song","details":"Slap bass, tight horns and a self-assured groove: The K. Funk is K.K.'s full funk workout, named with exactly as much modesty as it deserves.","image":"https://dodo.ac/np/images/4/4a/The_K._Funk_NH_Texture.png"},{"name":"K.K. Aria","rarity":"common","id":"k-k-aria","subtitle":"Song","details":"A soaring operatic showcase with dramatic strings, K.K. Aria lets the wandering dog show off a vocal range nobody expects from a busker.","image":"https://dodo.ac/np/images/3/36/K.K._Aria_NH_Texture.png"},{"name":"K.K. Blues","rarity":"common","id":"k-k-blues","subtitle":"Song","details":"Twelve bars, a wailing harmonica and plenty of ache: K.K. Blues is the catalogue's slow-burning lament for bad turnip prices and lost loves.","image":"https://dodo.ac/np/images/f/fa/K.K._Blues_NH_Texture.png"},{"name":"K.K. Calypso","rarity":"common","id":"k-k-calypso","subtitle":"Song","details":"Sunshine in song form, K.K. Calypso bounces along on steel-drum rhythms made for tropical islands, beach parties and Tortimer-style getaways.","image":"https://dodo.ac/np/images/8/87/K.K._Calypso_NH_Texture.png"},{"name":"K.K. Country","rarity":"common","id":"k-k-country","subtitle":"Song","details":"Fiddle, banjo and a two-step beat turn K.K. Country into a full hoedown, the natural soundtrack for farms, ranches and harvest-season rooms.","image":"https://dodo.ac/np/images/8/8d/K.K._Country_NH_Texture.png"},{"name":"K.K. Lullaby","rarity":"common","id":"k-k-lullaby","subtitle":"Song","details":"Music-box soft and deliberately sleepy, K.K. Lullaby closes the day gently, a favourite for nurseries, bedrooms and Dream Suite waiting rooms.","image":"https://dodo.ac/np/images/e/ee/K.K._Lullaby_NH_Texture.png"},{"name":"K.K. Parade","rarity":"common","id":"k-k-parade","subtitle":"Song","details":"Brassy and strutting, K.K. Parade sounds like a marching band coming down Main Street, all snare rolls, bright horns and waving-baton energy.","image":"https://dodo.ac/np/images/8/85/K.K._Parade_NH_Texture.png"},{"name":"K.K. Ragtime","rarity":"common","id":"k-k-ragtime","subtitle":"Song","details":"Honky-tonk piano rolls at full tilt in K.K. Ragtime, a cheerful slice of another century that suits saloons, theatres and vintage parlours.","image":"https://dodo.ac/np/images/8/88/K.K._Ragtime_NH_Texture.png"},{"name":"K.K. Reggae","rarity":"common","id":"k-k-reggae","subtitle":"Song","details":"One-drop rhythm and an unhurried bassline make K.K. Reggae the catalogue's most relaxed groove, island-approved for hammocks and sunset docks.","image":"https://dodo.ac/np/images/5/50/K.K._Reggae_NH_Texture.png"},{"name":"K.K. Salsa","rarity":"common","id":"k-k-salsa","subtitle":"Song","details":"Horn stabs and driving percussion build K.K. Salsa for dancing, a hot, brassy number that refuses to let any room sit still for long.","image":"https://dodo.ac/np/images/8/84/K.K._Salsa_NH_Texture.png"},{"name":"K.K. Stroll","rarity":"common","id":"k-k-stroll","subtitle":"Song","details":"An easy walking-tempo tune with a whistleable melody, K.K. Stroll is made for a lap around town, window-shopping and nowhere to be in particular.","image":"https://dodo.ac/np/images/a/ad/K.K._Stroll_NH_Texture.png"},{"name":"K.K. Swing","rarity":"common","id":"k-k-swing","subtitle":"Song","details":"Big-band horns snap and shuffle through K.K. Swing, a dance-hall number with enough bounce to fill Club LOL on its best Saturday nights.","image":"https://dodo.ac/np/images/b/b3/K.K._Swing_NH_Texture.png"},{"name":"K.K. Waltz","rarity":"common","id":"k-k-waltz","subtitle":"Song","details":"A proper three-quarter-time ballroom turn, K.K. Waltz gives formal rooms, wedding shoots and grand halls their most graceful soundtrack.","image":"https://dodo.ac/np/images/0/0e/K.K._Waltz_NH_Texture.png"},{"name":"K.K. Western","rarity":"common","id":"k-k-western","subtitle":"Song","details":"Harmonica and twanging guitar ride through K.K. Western, a frontier theme for cowboy corners, desert islands and high-noon fossil hunts.","image":"https://dodo.ac/np/images/a/a7/K.K._Western_NH_Texture.png"},{"name":"Golden Axe","rarity":"legendary","id":"golden-axe","subtitle":"Item","details":"The unbreakable pinnacle of axes, crafted with a gold nugget, this golden tool fells a full-grown tree in three swings and never loses its edge.","image":"https://dodo.ac/np/images/e/ec/Golden_Axe_NH_Icon.png"},{"name":"Golden Watering Can","rarity":"epic","id":"golden-watering-can","subtitle":"Item","details":"This golden can waters nine squares at once in New Horizons, and in earlier games it was the only way to turn a wilted black rose golden.","image":"https://dodo.ac/np/images/f/f7/Golden_Watering_Can_NH_Icon.png"},{"name":"Nook Miles Ticket","rarity":"epic","id":"nook-miles-ticket","subtitle":"Item","details":"Bought for 2,000 Nook Miles at Resident Services, one ticket buys a Dodo Airlines trip to a mystery island of resources, fruit and new faces.","image":"https://dodo.ac/np/images/f/f5/Nook_Miles_Ticket_NH_Icon.png"},{"name":"Royal Crown","rarity":"epic","id":"royal-crown","subtitle":"Item","details":"Sold at the Able Sisters for 1,200,000 Bells, the Royal Crown is the priciest hat in the series and the definitive flex for wealthy villagers.","image":"https://dodo.ac/np/images/c/cf/Royal_Crown_NH_Icon.png"},{"name":"Large Star Fragment","rarity":"epic","id":"large-star-fragment","subtitle":"Item","details":"These oversized shards wash ashore the morning after a meteor shower and are saved for zodiac furniture and other rare celestial DIY recipes.","image":"https://dodo.ac/np/images/4/47/Large_Star_Fragment_NH_Icon.png"},{"name":"Golden Shovel","rarity":"rare","id":"golden-shovel","subtitle":"Item","details":"A golden tool earned by helping Gulliver in the GameCube original and crafted from a gold nugget since, it digs Bells from glowing ground spots.","image":"https://dodo.ac/np/images/1/11/Golden_Shovel_NH_Icon.png"},{"name":"Golden Fishing Rod","rarity":"rare","id":"golden-fishing-rod","subtitle":"Item","details":"The final fishing upgrade, earned only by completing the fish section of the Critterpedia, its golden lure helps rare fish bite more readily.","image":"https://dodo.ac/np/images/5/5c/Golden_Rod_NH_Icon.png"},{"name":"Bell Bag","rarity":"rare","id":"bell-bag","subtitle":"Item","details":"Tied sacks hold Bells in set amounts, and a full 99,000-Bell bag in your pockets is the unmistakable sign of a very good week on the Stalk Market.","image":"https://dodo.ac/np/images/0/06/Bell_Bag_CF_Model.png"},{"name":"Pearl","rarity":"rare","id":"pearl","subtitle":"Item","details":"Found on the ocean floor while diving or traded by Pascal for a scallop, pearls are the key ingredient in the elegant mermaid furniture set.","image":"https://dodo.ac/np/images/7/7a/Pearl_NH_Icon.png"},{"name":"Gold Nugget","rarity":"rare","id":"gold-nugget","subtitle":"Item","details":"A rare ore knocked loose from rocks, gold nuggets are hoarded for golden tools, golden furniture and some of the game's flashiest DIY recipes.","image":"https://dodo.ac/np/images/d/de/Gold_Nugget_NH_Icon.png"},{"name":"Star Fragment","rarity":"rare","id":"star-fragment","subtitle":"Item","details":"Wish upon a shooting star and these glittering fragments appear on the beach next morning, ready to become wands and celestial furniture.","image":"https://dodo.ac/np/images/7/7a/Star_Fragment_NH_Icon.png"},{"name":"Pitfall Seed","rarity":"uncommon","id":"pitfall-seed","subtitle":"Item","details":"Bury one and whoever steps on the hidden mark falls straight in, arms flailing — a classic prank on villagers, visitors and unsuspecting friends.","image":"https://dodo.ac/np/images/b/b9/Pitfall_Seed_NH_Icon.png"},{"name":"Gyroid","rarity":"uncommon","id":"gyroid","subtitle":"Item","details":"Clay figures dug from the ground after rain, gyroids wobble, sing and keep rhythm, and no two collections of their odd little voices sound alike.","image":"https://dodo.ac/np/images/0/04/Gyroid_NH_Inv_Icon.png"},{"name":"Fossil","rarity":"uncommon","id":"fossil","subtitle":"Item","details":"Dug from star-shaped cracks in the ground, fossils go to Blathers for assessment, each one hopefully the missing piece of a museum skeleton.","image":"https://dodo.ac/np/images/b/b0/Fossil_NH_Icon.png"},{"name":"Leaf","rarity":"uncommon","id":"leaf","subtitle":"Item","details":"Every piece of furniture travels as this little green leaf in your pockets, an icon of the series since the very first game on the GameCube.","image":"https://dodo.ac/np/images/a/af/Leaf_NH_Icon.png"},{"name":"Genuine Painting","rarity":"uncommon","id":"genuine-painting","subtitle":"Item","details":"Among Redd's stock hides the real artwork the museum needs; spotting the genuine article means catching the tiny detail his forgeries get wrong.","image":"https://dodo.ac/np/images/7/78/Famous_Painting_NL_Model.png"},{"name":"Message in a Bottle","rarity":"uncommon","id":"message-in-a-bottle","subtitle":"Item","details":"Bottles wash up on the beach carrying DIY recipes from distant villagers, a daily reminder that someone across the sea is decorating too.","image":"https://dodo.ac/np/images/0/0a/Message_Bottle_NH_Inv_Icon.png"},{"name":"Turnips","rarity":"uncommon","id":"turnips","subtitle":"Item","details":"Daisy Mae sells these every Sunday morning, and the Stalk Market gamble begins: sell before Saturday, or watch your investment rot to nothing.","image":"https://dodo.ac/np/images/2/2e/Turnips_NH_Icon.png"},{"name":"Ladder","rarity":"uncommon","id":"ladder","subtitle":"Item","details":"A simple wooden ladder, crafted early in New Horizons, it first opened the island's cliffs and stayed in your tool ring for every climb after.","image":"https://dodo.ac/np/images/c/c9/Ladder_NH_Icon.png"},{"name":"Vaulting Pole","rarity":"uncommon","id":"vaulting-pole","subtitle":"Item","details":"Before bridges exist, this long pole is how you cross the river, planting it on the bank and launching yourself to the other side in one hop.","image":"https://dodo.ac/np/images/5/51/Vaulting_Pole_NH_Icon.png"},{"name":"Wetsuit","rarity":"uncommon","id":"wetsuit","subtitle":"Item","details":"Zip up and dive off the pier: the wetsuit opens the ocean's sea creatures, hidden pearls and scallops that summon a very philosophical otter.","image":"https://dodo.ac/np/images/1/1a/Wet_Suit_NH_Inv_Icon.png"},{"name":"Slingshot","rarity":"uncommon","id":"slingshot","subtitle":"Item","details":"The only way to claim the gifts that drift overhead on balloons, a well-timed slingshot shot drops presents that would otherwise float away.","image":"https://dodo.ac/np/images/e/ed/Slingshot_%28Red%29_NH_Icon.png"},{"name":"Golden Trout Model","rarity":"uncommon","id":"golden-trout-model","subtitle":"Item","details":"Commissioned from C.J. with three golden trout, this model honours one of the slipperiest rare river fish, a prize catch in any season it runs.","image":"https://dodo.ac/np/images/5/51/Golden_Trout_Model_NH_Icon.png"},{"name":"Bell Voucher","rarity":"uncommon","id":"bell-voucher","subtitle":"Item","details":"Bought with 500 Nook Miles and sold for 3,000 Bells, the Bell Voucher is the tidy exchange desk between the island's two currencies.","image":"https://dodo.ac/np/images/1/10/Bell_Voucher_NH_Icon.png"},{"name":"Fishing Rod","rarity":"common","id":"fishing-rod","subtitle":"Item","details":"The humble rod has waited beside patient players since 2001, watching for a shadow, a nibble and the split-second tug that means a catch.","image":"https://dodo.ac/np/images/a/a1/Fishing_Rod_%28Blue%29_NH_Icon.png"},{"name":"Net","rarity":"common","id":"net","subtitle":"Item","details":"For butterflies, dragonflies and wasps you'd rather not meet twice, the net is also good for one gentle, entirely deserved bonk on a villager.","image":"https://dodo.ac/np/images/9/90/Net_%28Red%29_NH_Icon.png"},{"name":"Shovel","rarity":"common","id":"shovel","subtitle":"Item","details":"One tool digs the fossils, hits the money rocks, buries the Bells and plants the flowers — the shovel quietly does half the work in town.","image":"https://dodo.ac/np/images/6/63/Shovel_%28Red%29_NH_Icon.png"},{"name":"Axe","rarity":"common","id":"axe","subtitle":"Item","details":"The everyday workhorse of the island, an axe gathers softwood, hardwood and plain wood from trees and, swung carelessly, fells them outright.","image":"https://dodo.ac/np/images/f/fa/Axe_NH_Icon.png"},{"name":"Watering Can","rarity":"common","id":"watering-can","subtitle":"Item","details":"Watering flowers keeps them blooming and, with help from visiting friends' cans, coaxes out the hybrid colours every garden designer chases.","image":"https://dodo.ac/np/images/c/c6/Watering_Can_%28Blue%29_NH_Icon.png"},{"name":"Coconut","rarity":"common","id":"coconut","subtitle":"Item","details":"Carried home from mystery islands and planted in the sand, coconuts grow into the palm trees that frame almost every island's beach entrance.","image":"https://dodo.ac/np/images/3/33/Coconut_NH_Icon.png"},{"name":"Apple","rarity":"common","id":"apple","subtitle":"Item","details":"The classic native fruit, red on the branches of the series' very first trees, apples sell, gift and decorate as the default orchard crop.","image":"https://dodo.ac/np/images/d/d7/Apple_NH_Icon.png"},{"name":"Bamboo Shoot","rarity":"common","id":"bamboo-shoot","subtitle":"Item","details":"Plant a bamboo shoot and a grove follows, bringing spring's young bamboo and a whole family of DIY recipes in greens and natural wood.","image":"https://dodo.ac/np/images/1/18/Bamboo_Shoot_NH_Icon.png"},{"name":"Wood","rarity":"common","id":"wood","subtitle":"Item","details":"Three chops per tree makes wood the backbone crafting material of the island, feeding everything from flimsy tools to full furniture series.","image":"https://dodo.ac/np/images/a/a2/Wood_NH_Icon.png"},{"name":"Iron Nugget","rarity":"common","id":"iron-nugget","subtitle":"Item","details":"Knocked from rocks with a well-fed swing, iron nuggets are the staple metal behind sturdier tools, fences and the Nook's Cranny shop upgrade.","image":"https://dodo.ac/np/images/f/fd/Iron_Nugget_NH_Icon.png"},{"name":"Clay","rarity":"common","id":"clay-item","subtitle":"Item","details":"Soft lumps dug from struck rocks, clay becomes bricks, pots, partitions and ocarinas — humble material, surprisingly long list of second lives.","image":"https://dodo.ac/np/images/4/4c/Clay_NH_Icon.png"},{"name":"Conch","rarity":"common","id":"conch","subtitle":"Item","details":"The big spiral shell found along the shoreline, a conch can be sold at Nook's Cranny or saved for shell furniture, arches and summer DIYs.","image":"https://dodo.ac/np/images/2/22/Spiral_Shell_NH_Icon.png"},{"name":"Balloon Present","rarity":"common","id":"balloon-present","subtitle":"Item","details":"Roughly every few minutes the wind carries a gift box dangling from a balloon across the island — hear the whoosh, look up, and take the shot.","image":"https://dodo.ac/np/images/0/0d/Balloon_with_Present_PG_Icon.png"},{"name":"Wasp Nest","rarity":"common","id":"wasp-nest","subtitle":"Item","details":"Shake the wrong tree and this drops, hornets pouring out after you; run for a building, or turn fast and catch the whole swarm in your net.","image":"https://dodo.ac/np/images/5/56/Wasp_Nest_NH_Icon.png"},{"name":"Tree Branch","rarity":"common","id":"tree-branch","subtitle":"Item","details":"A humble stick shaken loose from any tree, the tree branch is where it all starts: seven of them become your very first flimsy fishing rod.","image":"https://dodo.ac/np/images/5/5d/Tree_Branch_NH_Icon.png"},{"name":"Clump of Weeds","rarity":"common","id":"clump-of-weeds","subtitle":"Item","details":"Pulled by the handful to tidy a new island, weeds sell for a few Bells each — the first honest work Timmy ever pays a new Resident Rep for.","image":"https://dodo.ac/np/images/8/82/Clump_of_Weeds_NH_Icon.png"},{"name":"Animal Crossing: New Horizons","rarity":"chase","id":"animal-crossing-new-horizons","subtitle":"Game","details":"Released in 2020 for Nintendo Switch, New Horizons strands you on a deserted island you build from nothing, and became the series' best-seller.","image":"https://dodo.ac/np/images/7/76/NH_Box_NA.png"},{"name":"Animal Crossing: New Leaf","rarity":"legendary","id":"animal-crossing-new-leaf","subtitle":"Game","details":"Released in 2012 for Nintendo 3DS, New Leaf made you the mayor, adding ordinances, public works and Isabelle to a town you governed and grew.","image":"https://dodo.ac/np/images/e/e2/NL_Box_NA.jpg"},{"name":"Animal Crossing","rarity":"legendary","id":"animal-crossing","subtitle":"Game","details":"The 2001 GameCube original brought the series west with real-time living, NES games to play, K.K. concerts and a loan from a very patient tanuki.","image":"https://dodo.ac/np/images/d/d1/PG_Box_NA.png"},{"name":"Animal Crossing: Wild World","rarity":"epic","id":"animal-crossing-wild-world","subtitle":"Game","details":"Released in 2005 for Nintendo DS, Wild World took the village portable and online for the first time, letting friends visit through Wi-Fi.","image":"https://dodo.ac/np/images/d/d9/WW_Box_NA.jpg"},{"name":"Animal Crossing: City Folk","rarity":"epic","id":"animal-crossing-city-folk","subtitle":"Game","details":"Released in 2008 for Wii, City Folk added a bus ride to the City, home to GracieGrace, Shampoodle, the theatre and Katrina's fortune tent.","image":"https://dodo.ac/np/images/0/09/CF_Box_NA.jpg"},{"name":"Toy Day","rarity":"epic","id":"toy-day","subtitle":"Event","details":"On December 24, Jingle the black-nosed reindeer needs your help delivering the right present to every villager — the series' Christmas Eve.","image":"https://dodo.ac/np/images/4/48/Toy_Day_NH_Northern_Hemisphere.jpg"},{"name":"Halloween","rarity":"epic","id":"halloween","subtitle":"Event","details":"On October 31, Jack, Czar of Halloween, rules the plaza while villagers in costume demand candy and trade spooky furniture for every piece.","image":"https://dodo.ac/np/images/a/a9/NH_Halloween_trick_or_treat.jpg"},{"name":"Animal Crossing: Pocket Camp","rarity":"rare","id":"animal-crossing-pocket-camp","subtitle":"Game","details":"Released in 2017 for mobile, Pocket Camp ran a cosy campsite of visiting animals and craftable furniture for seven years of seasonal events.","image":"https://dodo.ac/np/images/2/21/PC_Logo_English.png"},{"name":"Animal Crossing: New Horizons — Happy Home Paradise","rarity":"rare","id":"animal-crossing-new-horizons-happy-home-paradise","subtitle":"Game","details":"Released in 2021 as New Horizons' paid DLC, Happy Home Paradise joins Paradise Planning to design dream vacation homes on a resort archipelago.","image":"https://dodo.ac/np/images/6/6d/HHP_Key_Art_NA.jpg"},{"name":"Festivale","rarity":"rare","id":"festivale","subtitle":"Event","details":"Before Lent, Pavé the peacock fills the plaza with confetti and demands feathers, trading Festivale furniture for every colour you bring him.","image":"https://dodo.ac/np/images/1/1b/NH_Promo_Festivale_Pav%C3%A9.jpg"},{"name":"Bunny Day","rarity":"rare","id":"bunny-day","subtitle":"Event","details":"Zipper T. Bunny hides six kinds of eggs in trees, rocks, water and sky, filling pockets island-wide in the run-up to this spring egg hunt.","image":"https://dodo.ac/np/images/6/6b/NH_Bunny_Day_Multiple_Balloons.png"},{"name":"Fishing Tourney","rarity":"rare","id":"fishing-tourney","subtitle":"Event","details":"Held four times a year, the Fishing Tourney challenges you to catch as many fish as possible in three-minute rounds, hosted by C.J. in New Horizons.","image":"https://dodo.ac/np/images/5/59/NH_C.J.%27s_Fishing_Tourney.jpg"},{"name":"Animal Crossing: Happy Home Designer","rarity":"uncommon","id":"animal-crossing-happy-home-designer","subtitle":"Game","details":"Released in 2015 for Nintendo 3DS, Happy Home Designer dropped the loan and the chores to focus purely on decorating homes for villagers.","image":"https://dodo.ac/np/images/0/0b/HHD_Box_North_America.png"},{"name":"Animal Crossing Plaza","rarity":"uncommon","id":"animal-crossing-plaza","subtitle":"Game","details":"A free Wii U app from 2013, Plaza gathered the series' villagers in a Miiverse-linked hub between games, a small social space rather than a game.","image":"https://dodo.ac/np/images/9/98/Animal_Crossing_Plaza_Logo_English.png"},{"name":"Bug-Off","rarity":"uncommon","id":"bug-off","subtitle":"Event","details":"Across the summer months, Flick hosts the Bug-Off in New Horizons, scoring every bug you net in three-minute rounds for trophies and bug merch.","image":"https://dodo.ac/np/images/a/aa/NH_Flick%27s_Bug-Off.jpg"},{"name":"Turkey Day","rarity":"uncommon","id":"turkey-day","subtitle":"Event","details":"For this harvest feast, Franklin the turkey chef sends you hunting secret ingredients, rewarding each dish you help perfect with festive furniture.","image":"https://dodo.ac/np/images/a/a8/NH_Turkey_Day_All_Dishes.jpg"},{"name":"May Day","rarity":"uncommon","id":"may-day","subtitle":"Event","details":"During this spring event, Tom Nook's maze tour strands you on a hedge-labyrinth island with limited tools and a meeting with Rover at its heart.","image":"https://dodo.ac/np/images/4/43/Rover_NH_May_Day_Southern_Hemisphere.jpg"},{"name":"Animal Crossing: amiibo Festival","rarity":"common","id":"animal-crossing-amiibo-festival","subtitle":"Game","details":"Released in 2015 for Wii U, amiibo Festival turned the village into a board game played with amiibo figures, the series' strangest detour.","image":"https://dodo.ac/np/images/b/bd/AF_Box_North_America.jpg"},{"name":"Countdown","rarity":"common","id":"countdown","subtitle":"Event","details":"On New Year's Eve the plaza fills with party poppers, a giant countdown clock and Tom Nook's light sticks, building to fireworks at midnight.","image":"https://dodo.ac/np/images/e/ec/NH_Countdown_Resident_Services.jpg"},{"name":"Wedding Season","rarity":"common","id":"wedding-season","subtitle":"Event","details":"All through June, Reese and Cyrus renew their vows at Harv's Island, and you stage and photograph their anniversary party for heart crystals.","image":"https://dodo.ac/np/images/d/dd/NH_Promo_Wedding_Season_2022.jpg"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
